"use client";
import Link from "next/link";
import { useState } from "react";
import { Badge } from "@/components/ui/Badge";
import { accessInput } from "./PayoutAccountEditor";
export type AccessQueueItem = { branchId: string; branchName: string; companyName: string; status: string; requestLabel: string; submittedAt: string | null; needsReconfirmation: boolean; paused: boolean };
export function PaymentAccessQueue({ items, now }: { items: AccessQueueItem[]; now: string }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState("PENDING");
  const shown = items.filter(item => `${item.companyName} ${item.branchName}`.toLowerCase().includes(query.toLowerCase()) && (status === "ALL" || status === "CHANGES" ? status === "ALL" || item.needsReconfirmation : item.status === status));
  function age(date: string | null) { if (!date) return "Not submitted"; const hours = Math.max(0, Math.floor((new Date(now).getTime() - new Date(date).getTime()) / 3600000)); return hours < 1 ? "Less than an hour ago" : hours < 24 ? `${hours} hour${hours === 1 ? "" : "s"} ago` : `${Math.floor(hours / 24)} days ago`; }
  return <div className="space-y-5"><header><h1 className="text-section-title">Branch payment access</h1><p className="mt-1 text-sm text-fg-muted">Review each branch's request and payout details.</p></header><div className="grid gap-3 sm:grid-cols-[1fr_14rem]"><label className="grid gap-1 text-sm">Search vendors or branches<input className={accessInput} type="search" value={query} onChange={event => setQuery(event.target.value)} /></label><label className="grid gap-1 text-sm">Request status<select className={accessInput} value={status} onChange={event => setStatus(event.target.value)}><option value="PENDING">In review</option><option value="CHANGES">Needs confirmation</option><option value="APPROVED">Approved</option><option value="REJECTED">Not approved</option><option value="REVOKED">Revoked</option><option value="ALL">All requests</option></select></label></div>
    <p role="status" className="text-sm text-fg-muted">{shown.length} request{shown.length === 1 ? "" : "s"}</p><ul className="divide-y divide-border border-y border-border">{shown.map(item => <li key={item.branchId} className="flex flex-col justify-between gap-3 py-4 sm:flex-row sm:items-center"><div className="space-y-1"><p className="font-semibold">{item.companyName}</p><p className="text-sm">{item.branchName}</p><div className="flex flex-wrap gap-2"><Badge tone={item.status === "APPROVED" ? "success" : "warning"}>{item.requestLabel}</Badge>{item.paused && <Badge tone="warning">Payments paused</Badge>}</div><p className="text-xs text-fg-muted">Submitted {age(item.submittedAt)}</p></div><Link href={`/vendors/payment-access/${item.branchId}`} className="min-h-11 content-center text-sm font-medium underline">Review request<span className="sr-only"> for {item.companyName}, {item.branchName}</span></Link></li>)}</ul>{!shown.length && <p className="text-sm text-fg-muted">No matching payment-access requests.</p>}
  </div>;
}
